'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const Career=AstraCareerCore;let careerState=Career.empty();
const C=AstraCore,D=AstraData,storageKey='astra.saved.v1';
let current={date:'1996-08-16',name:'',example:true},activeTab='overview',toastTimer,checks=new Set(),printTab=null;
function readSaved(){try{const a=JSON.parse(localStorage.getItem(storageKey)||'[]');return Array.isArray(a)?a.filter(x=>x&&typeof x.date==='string'&&!C.validate(x.date)&&typeof x.name==='string').map(x=>({date:x.date,name:x.name.slice(0,24),career:Career.normalize(x.career)})).slice(0,30):[];}catch{return [];}}
let saved=readSaved();
function storeSaved(){try{localStorage.setItem(storageKey,JSON.stringify(saved));$('#saved-count').textContent=saved.length;return true;}catch{toast('瀏覽器無法儲存，請改用下載報告保留內容。');return false;}}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3300);}
function model(){const s=D.signs[C.signIndex(current.date)],calc=C.lifePath(current.date),n=D.numbers[calc.number];return {s,n,calc,title:`${s.element==='火'?'熱情':s.element==='土'?'沉穩':s.element==='風'?'靈思':'共感'}${n.role}`,date:current.date.replace(/-/g,' / ')};}
const chips=tags=>`<div class="chip-row">${tags.map(t=>`<span class="chip">${esc(t)}</span>`).join('')}</div>`;
const heading=(title,en)=>`<div class="section-title"><span>✧</span><h3>${title}</h3><small>${en}</small><span class="line"></span></div>`;
function details(m){return `<details><summary>查看星座判定與生命靈數計算過程</summary><div>出生日期：${m.date}（西曆）<br>星座：依固定月日區間判定為 ${m.s.glyph} ${m.s.name}。${m.s.start>m.s.end?'跨年區間':''}${range(m.s)}。<br>生命靈數：將生日的所有數字相加，逐次加總至個位數；過程遇到 11、22、33 即保留。<div class="calc">${m.calc.digits.join(' + ')} = ${m.calc.steps.join(' → ')}${m.calc.number>9?`（大師數 ${m.calc.number}，基底 ${m.calc.base}）`:''}</div>靈數流派存在不同的加總方式；本 App 使用「全部數字先相加」法，未先對年月日分別約簡。星座交界日期的實際太陽位置隨年份、出生時間與地點而異，此處採常見固定日期近似，未計算星盤、上升或月亮星座。</div></details>`;}
function range(s){const fmt=v=>`${Math.floor(v/100)}/${v%100}`;return `（${fmt(s.start)}–${fmt(s.end)}）`;}
function synthesis(m){const {s,n}=m;return `如果你認同${s.name}的「${s.tags[0]}」與生命靈數 ${m.calc.number} 的「${n.tags[0]}」，你的角色主題可能是：${n.gift}。${s.role}提供你面對世界的表達方式，${n.title}則提供一個觀察內在需求的角度。兩者可以互相支持，也可能在壓力下互相拉扯；請用真實經驗選擇貼近你的部分。`;}
function tension(m){const {s,n}=m;return `當你遇到「${s.trigger.replace(/。$/,'')}」的情境，可能先出現星座原型中的反應：${s.flaw}同時，${n.title}的象徵也提醒你留意：${n.flaw}這是反思用的假設，並非對你的判定。回想一次具體經驗，分清楚發生了什麼、你如何解讀，以及下次可以換哪個行動。`;}
function journey(m){return `<div class="detail-card"><div class="kicker">YOUR STORY IS STILL UNFOLDING</div><h3>命運敘事 · 由你續寫的故事</h3><p>這份「命運」報告是一個角色成長框架，不預言事件、吉凶或人生結果。用三個階段觀察自己目前的選擇。</p><div class="path-card"><span class="step-number">01</span><div><h4>起點 · 看見想守住的東西</h4><p>${m.s.motive}靈數的象徵需求是：${m.n.motive}</p></div></div><div class="path-card"><span class="step-number">02</span><div><h4>轉折 · 辨認慣性反應</h4><p>${m.s.flaw}${m.n.flaw}當你看見這些反應時，可以把它當作暫停與重新選擇的訊號。</p></div></div><div class="path-card"><span class="step-number">03</span><div><h4>新篇章 · 把能力用在重要之處</h4><p>${m.n.arc}。從一個可重複的小行動開始，而不必把自己變成另一種人。</p></div></div></div>`;}
function overview(m){return `<div class="identity-grid"><article class="identity-card sun"><div class="card-top">☉ 太陽星座 <span class="tiny-badge">性格底色</span></div><div class="identity-symbol">${m.s.glyph}</div><h3>${m.s.name}<small>${m.s.en} · ${range(m.s).replace(/[（）]/g,'')}</small></h3><p class="card-caption">${m.s.element}象星座 · ${m.s.mode}型<br>原型：${m.s.role}</p>${chips(m.s.tags)}</article><article class="identity-card number"><div class="card-top">∞ 生命靈數 <span class="tiny-badge">內在驅動</span></div><div class="identity-symbol">${m.calc.number}</div><h3>${m.n.title}<small>${m.n.en}</small></h3><p class="card-caption">${m.calc.number>9?'大師數象徵 · 基底 '+m.calc.base:'人生路徑數 '+m.calc.number}<br>成長主題：${m.n.tags.join('與')}</p>${chips(m.n.tags)}</article><article class="identity-card fusion"><div class="card-top">✧ 你的核心角色 <span class="tiny-badge">雙重解讀</span></div><h3>${m.title}</h3><div class="fusion-equation">${m.s.name} × 生命靈數 ${m.calc.number}</div><p class="card-caption">${m.n.gift}。<br>讓${m.s.tags[0]}有方向，讓${m.n.tags[0]}有溫度。</p>${chips([m.s.tags[0],m.n.tags[0],'自我成長'])}</article></div>${heading('你內在的兩種力量','THE INNER SYNERGY')}<div class="insight-card"><span class="quote">“</span><div><h3>「${m.s.tags[0]}」是你的光，<br>「${m.n.tags[0]}」讓這束光找到方向。</h3><p>${synthesis(m)}</p></div></div>${heading('天賦與成長的交會','GIFTS & GROWTH')}<div class="two-columns"><article class="detail-card"><div class="kicker">01 / NATURAL GIFTS</div><h3>你可以善用的力量</h3><p>${m.s.desc}</p><ul><li>星座的表達優勢：${m.s.tags.join('、')}。</li><li>靈數的發展方向：${m.n.desc}</li></ul></article><article class="detail-card"><div class="kicker">02 / GROWING EDGE</div><h3>讓優點不再成為負擔</h3><p>${m.s.flaw}${m.n.flaw}</p><ul><li>先試一個調整：${m.s.practice}</li><li>提醒自己：你不需要符合所有描述，才值得被理解。</li></ul></article></div>${details(m)}`;}
function personality(m){return `${heading('性格的表層與深處','PERSONALITY & MOTIVATION')}<div class="two-columns"><article class="detail-card"><div class="kicker">THE WAY YOU SHOW UP</div><h3>${m.s.role} · 如何面對世界</h3><p>${m.s.desc}</p><ul><li>元素象徵：${m.s.element}象，${{火:'熱情、意志與行動',土:'現實、累積與感官',風:'思想、交流與觀點',水:'情感、共鳴與想像'}[m.s.element]}。</li><li>模式象徵：${m.s.mode}，${{開創:'主動啟動與定義方向',固定:'投入、維護與持續深化',變動:'調整、串連與回應變化'}[m.s.mode]}。</li><li>傳統／現代守護星象徵：${m.s.ruler}。</li></ul></article><article class="detail-card"><div class="kicker">WHAT MOVES YOU</div><h3>${m.n.title} · 內在動機</h3><p>${m.n.desc}</p><ul><li>星座需求：${m.s.need}</li><li>靈數需求：${m.n.motive}</li></ul></article></div>${heading('壓力下的你','THE SHADOW PATTERN')}<div class="insight-card"><span class="quote">“</span><div><h3>先理解反應，才有新的選擇。</h3><p>${tension(m)}</p></div></div>${heading('把理解帶進日常','IN EVERYDAY LIFE')}<div class="two-columns"><article class="detail-card"><div class="kicker">RELATIONSHIPS</div><h3>關係中的互動</h3><p>${m.s.relation}</p></article><article class="detail-card"><div class="kicker">WORK & CREATIVITY</div><h3>工作與創造方式</h3><p>${m.s.work}</p></article></div><div style="margin-top:18px">${journey(m)}</div>`;}
function characters(m){const char=(c,k,sy)=>`<article class="character-card"><div class="kicker">${k}</div><div class="character-art" aria-hidden="true">${sy}</div><h3>${c.name}</h3><small>${c.work}</small><p>${c.trait}</p><div class="lesson">↗ 成長啟示<br>${c.lesson}</div></article>`;return `${heading('故事裡，遇見另一個自己','CHARACTER MIRRORS')}<div class="character-grid">${char(m.s.character,'01 / ZODIAC ARCHETYPE',m.s.character.symbol)}${char(m.n.character,'02 / LIFE PATH ARCHETYPE','✦')}</div><p class="note-box">以上是編輯選擇的文學或影視角色類比，並非角色的官方星座、生日或靈數設定。作品版本不同，角色表現也可能不同；你可以同意、保留或重新解讀。</p><div class="detail-card"><div class="kicker">YOUR OWN CHARACTER ARC</div><h3>你的主角，不必照著劇本走</h3><p>如果以「${m.title}」為主角，故事的驅動是：${m.n.motive}而值得面對的衝突，是如何在「${m.s.tags[0]}」與「${m.n.tags[0]}」之間，保有彈性而不犧牲自己的需要。</p><ul><li>主角的資源：${m.s.tags.join('、')}，加上${m.n.gift}的方向。</li><li>容易重演的困境：${m.s.flaw}</li><li>新的選擇：${m.n.practice}</li><li>寫給自己的提問：如果不必證明任何事，我現在真正想守護的是什麼？</li></ul></div>`;}
function practices(m){return [
 {title:'第 1 天 · 記錄一次真實反應',body:`遇到壓力時，寫下事件、感受和反應。特別觀察：${m.s.flaw}`},
 {title:'第 2–3 天 · 練習星座的成長邊界',body:m.s.practice},
 {title:'第 4–5 天 · 練習靈數的另一種可能',body:m.n.practice},
 {title:'第 6 天 · 向可信任的人確認',body:'詢問：「最近和我相處時，哪個行動讓你舒服？哪個地方可以調整？」先聽完，只確認具體例子。'},
 {title:'第 7 天 · 回顧，留下有效的小步驟',body:'選一個有效行動繼續一週。問自己：我更了解需求了嗎？哪些描述其實不適合我？把不適合的放下。'}
 ];}
function growth(m){return `${heading('看見弱點，練出新的回應','A GENTLER WAY FORWARD')}<div class="two-columns"><article class="detail-card"><div class="kicker">ZODIAC / PRACTICE 01</div><h3>從「${m.s.tags[0]}」的另一面開始</h3><p><span class="accent-text">留意的慣性：</span>${m.s.flaw}</p><p style="margin-top:12px"><span class="accent-text">可採取的行動：</span>${m.s.practice}</p></article><article class="detail-card"><div class="kicker">LIFE PATH / PRACTICE 02</div><h3>${m.n.title}的成長練習</h3><p><span class="accent-text">留意的慣性：</span>${m.n.flaw}</p><p style="margin-top:12px"><span class="accent-text">可採取的行動：</span>${m.n.practice}</p></article></div>${heading('給自己七天，試一種新可能','YOUR 7-DAY PRACTICE')}<div class="detail-card"><p>把理解變成小而具體的行動。勾選記錄只保留在本次頁面；重新產生報告或重新整理後會重設。</p><div class="progress-line"><div class="progress-track"><div id="progress-bar"></div></div><span id="progress-text">0 / 5 項練習</span></div>${practices(m).map((p,i)=>`<div class="practice"><input id="practice-${i}" type="checkbox" data-check="${i}" ${checks.has(i)?'checked':''}><label for="practice-${i}">${p.title}<small>${p.body}</small></label></div>`).join('')}</div><div class="insight-card" style="margin-top:18px"><span class="quote">“</span><div><h3>你可以理解自己的模式，<br>也可以選擇下一步。</h3><p>${m.n.arc}。用生日作為提問的起點，讓日常經驗成為答案的依據。</p></div></div>`;}
const renderers={overview,personality,characters,growth,career:m=>AstraCareerUI.render(careerState,m,current)};
function render(all=false){
 const m=model();$('#report-title').innerHTML=`${esc(current.name?current.name+'的星序檔案':'你的星序檔案')} ${current.example?'<span id="example-label">範例預覽</span>':''}`;
 $('#report-subtitle').textContent=`${current.example?'以 1996 / 08 / 16 為例 · 輸入生日，探索你的版本':m.date+' · '+m.s.name+' × 生命靈數 '+m.calc.number+' · 象徵性自我探索報告'}`;
 $('#report-content').innerHTML=(all?Object.keys(renderers):[activeTab]).map(t=>`<div class="report-panel" role="tabpanel" aria-label="${{overview:'總覽',personality:'性格與動機',characters:'角色映照',growth:'成長指引',career:'生涯運數'}[t]}">${renderers[t](m)}</div>`).join('');
 $$('.report-tabs button').forEach(b=>{b.classList.toggle('active',b.dataset.tab===activeTab);b.setAttribute('aria-selected',String(b.dataset.tab===activeTab));b.tabIndex=b.dataset.tab===activeTab?0:-1;});
 $$('#report-content [data-check]').forEach(el=>el.addEventListener('change',()=>{const i=Number(el.dataset.check);el.checked?checks.add(i):checks.delete(i);updateProgress();}));
 if(!all&&activeTab==='career')AstraCareerUI.bind(careerState,m,current,(repaint=true)=>repaint?render():updateSave(),toast,()=>{$('#birth-title').scrollIntoView({behavior:'smooth'});$('#birthday').focus({preventScroll:true});});
 updateProgress();updateSave();
}
function updateProgress(){if($('#progress-bar')){$('#progress-bar').style.width=checks.size/5*100+'%';$('#progress-text').textContent=`${checks.size} / 5 項練習`;}}
function updateSave(){const item=saved.find(x=>x.date===current.date&&x.name===current.name),same=item&&JSON.stringify(Career.normalize(item.career))===JSON.stringify(Career.normalize(careerState));$('#save-button').innerHTML=item&&!current.example?(same?'♥ <span>已收藏</span>':'↻ <span>更新收藏</span>'):'♡ <span>收藏報告</span>';$('#saved-count').textContent=saved.length;}
function activate(tab){activeTab=tab;render();}
function showDialog(html){$('#dialog-content').innerHTML=html;if(!$('#info-dialog').open)$('#info-dialog').showModal();}
function showMethod(){showDialog(`<h2>一張生日，兩種觀察視角。</h2><p>星序把西方太陽星座的常見象徵，與生命靈數的人生路徑數結合，提供一份可供反思的角色報告。內容由固定規則與編輯文字組合，不是即時 AI 占卜。</p><h3>01 · 星座如何判定？</h3><p>用生日的月、日比對十二星座的固定日期區間，例如獅子座為 7/23–8/22。實際太陽換座時間會因年份、時間、地點而異；交界日前後出生者，此處只是近似。沒有出生時間與地點，因此不推算上升、月亮或完整星盤。</p><h3>02 · 靈數如何計算？</h3><p>使用西曆年月日，將全部數字先相加，再逐次相加，直到 1–9；過程出現 11、22、33 時保留。例如 1996/08/16：1+9+9+6+0+8+1+6 = 40 → 4。不同流派可能有不同算法。大師數只是命名慣例，不表示優越或特殊責任。</p><h3>03 · 角色與命運是什麼？</h3><p>角色是故事中的象徵類比，不是角色官方生日或心理判定。「命運」以動機、盲點、選擇的成長敘事呈現，不預測人生事件。生日不能可靠決定人格或未來；請用自己的經驗檢視描述，只保留有幫助的部分。</p><h3>04 · 生涯運數與 DISC 如何結合？</h3><p>生涯運數沿用生命靈數作為象徵性動機提問；16 題 DISC 自編練習則根據實際回答計算四類平均，每類 4 題、每題 1–5 分，同分保留並列。生日不參與 DISC 計分。透過記錄情境、替代行動與結果，把自我觀察轉成日常練習。這不是官方或經標準化驗證的心理測驗。</p><h3>05 · 我的生日會被保存嗎？</h3><p>計算在瀏覽器內完成，不傳送生日或稱呼至伺服器。點選「收藏報告」才會把生日、稱呼、DISC 作答與已加入報告的行動紀錄保存在這個瀏覽器的 localStorage。可到「我的收藏」逐項刪除；下載檔案則由你自行保管。</p>`);}
function showSaved(){showDialog(`<h2>我的收藏 <small style="font:12px var(--sans);color:#9e86af">${saved.length} / 30</small></h2><p>只保存在這個瀏覽器，換裝置不會同步。重新開啟會以目前版本的解讀文字產生報告。</p>${saved.length?saved.map((x,i)=>{const s=D.signs[C.signIndex(x.date)];return `<div class="saved-item"><div><strong>${esc(x.name||'我的星序檔案')}</strong><p>${x.date} · ${s.name} × ${C.lifePath(x.date).number}</p></div><div><button class="secondary-button" data-open="${i}">開啟 ↗</button><button class="icon-button" data-remove="${i}" aria-label="刪除 ${esc(x.name||x.date)} 的收藏">×</button></div></div>`;}).join(''):'<div class="insight-card" style="display:block;margin-top:20px"><h3>為自己留一份星序檔案。</h3><p>輸入生日並產生報告後，點選「收藏報告」即可在此找到。</p></div>'}`);
 $$('[data-open]').forEach(b=>b.onclick=()=>{const x=saved[Number(b.dataset.open)];current={date:x.date,name:x.name,example:false};careerState=Career.normalize(x.career);checks.clear();$('#birthday').value=x.date;$('#nickname').value=x.name;activate('overview');$('#info-dialog').close();$('#report').scrollIntoView({behavior:'smooth'});toast('已開啟收藏的星序檔案。');});
 $$('[data-remove]').forEach(b=>b.onclick=()=>{const old=[...saved];saved.splice(Number(b.dataset.remove),1);if(storeSaved()){showSaved();updateSave();toast('已刪除此收藏。');}else saved=old;});
}
function reportText(){const m=model();return `# 星序 ASTRA｜${current.name||'我的'}核心角色報告${current.example?'（範例）':''}\n\n生日：${m.date}\n星座：${m.s.name} ${range(m.s)}\n生命靈數：${m.calc.number}\n核心角色：${m.title}\n\n## 01 核心屬性\n星座原型：${m.s.role}；${m.s.element}象／${m.s.mode}；守護星象徵：${m.s.ruler}\n${m.s.desc}\n\n靈數原型：${m.n.title}\n${m.n.desc}\n\n## 02 星座與靈數的結合\n${synthesis(m)}\n\n## 03 需求與動機\n${m.s.motive}\n情感需要：${m.s.need}\n靈數需求：${m.n.motive}\n\n## 04 盲點與壓力\n${tension(m)}\n\n## 05 關係與工作\n關係：${m.s.relation}\n工作與創造：${m.s.work}\n\n## 06 經典角色映照\n${m.s.character.name}｜${m.s.character.work}\n${m.s.character.trait}\n啟示：${m.s.character.lesson}\n\n${m.n.character.name}｜${m.n.character.work}\n${m.n.character.trait}\n啟示：${m.n.character.lesson}\n角色僅為編輯類比，不是官方星座或生日設定。\n\n## 07 命運敘事與選擇\n這是成長框架，不預言事件或吉凶。\n起點：${m.s.motive}\n轉折：辨認「${m.s.flaw}」與「${m.n.flaw}」的慣性。\n新篇章：${m.n.arc}。\n\n## 08 人格弱點的改善練習\n星座：${m.s.practice}\n靈數：${m.n.practice}\n\n## 09 七天行動\n${practices(m).map(p=>p.title+'\n'+p.body).join('\n\n')}\n\n## 計算說明\n${m.calc.digits.join(' + ')} = ${m.calc.steps.join(' → ')}\n將全部生日數字先加總，逐次相加至個位數，過程保留 11、22、33。其他流派可能有不同結果。\n星座採固定日期近似；交界日實際太陽位置需年份、時間與地點資料。未計算上升或月亮星座。\n\n星座與靈數是象徵系統，供娛樂及自我反思，不是科學人格評估或未來預測。你的選擇與經驗比任何標籤都重要。\n\n— 星序 ASTRA`;}
$('#birth-form').addEventListener('submit',e=>{e.preventDefault();const error=C.validate($('#birthday').value);$('#form-error').textContent=error;$('#birthday').setAttribute('aria-invalid',error?'true':'false');if(error){$('#birthday').focus();return;}if(current.example||current.date!==$('#birthday').value)careerState=Career.empty();current={date:$('#birthday').value,name:$('#nickname').value.trim().slice(0,24),example:false};checks.clear();activate('overview');$('#report').scrollIntoView({behavior:'smooth',block:'start'});toast('你的星序檔案已完成。');});
$('#birthday').addEventListener('input',()=>{$('#form-error').textContent='';$('#birthday').removeAttribute('aria-invalid');});
$$('.report-tabs button').forEach((b,i)=>{b.onclick=()=>activate(b.dataset.tab);b.addEventListener('keydown',e=>{const tabs=$$('.report-tabs button');let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();activate(tabs[next].dataset.tab);tabs[next].focus();}});});
$('#save-button').onclick=()=>{if(current.example){toast('請先輸入生日並產生報告。');$('#birthday').focus();return;}const i=saved.findIndex(x=>x.date===current.date&&x.name===current.name);if(i<0&&saved.length>=30){toast('收藏已達 30 份，請先刪除舊收藏。');showSaved();return;}const old=[...saved],item={date:current.date,name:current.name,career:Career.normalize(careerState)};if(i>=0)saved[i]=item;else saved.unshift(item);if(storeSaved()){updateSave();toast('已保存生日、行為自評與行動紀錄。');}else saved=old;};
$('#download-button').onclick=()=>{const blob=new Blob(['\uFEFF'+reportText()+AstraCareerUI.text(careerState,model())],{type:'text/markdown;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`ASTRA-${current.date}${current.example?'-範例':''}.md`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已下載完整文字報告。');};
window.addEventListener('beforeprint',()=>{printTab=activeTab;render(true);$$('details').forEach(x=>x.open=true);});
window.addEventListener('afterprint',()=>{if(printTab){activeTab=printTab;printTab=null;render();}});
$('#print-button').onclick=()=>window.print();
$('#nav-explore').onclick=()=>{$('#birth-title').scrollIntoView({behavior:'smooth',block:'center'});$('#birthday').focus({preventScroll:true});};
$('#nav-career').onclick=()=>{activate('career');$('#report').scrollIntoView({behavior:'smooth'});};
$('#nav-saved').onclick=showSaved;
$('#nav-method').onclick=showMethod;
$('#method-inline').onclick=showMethod;
$('#about-top').onclick=()=>showDialog('<h2>認識自己，是一場溫柔的探索。</h2><p>星序 ASTRA 是一份互動式的生日札記。以十二星座與生命靈數為線索，從故事角色、內在動機到日常練習，邀請你用新的視角理解自己。</p><p>這些象徵不會定義你的全部。遇到不符合的描述，可以放下；遇到有共鳴的提問，可以帶回生活驗證。真正寫下下一頁的人，是你。</p><h3>使用方式</h3><p>輸入西曆生日 → 閱讀五個報告分頁 → 挑選成長練習。你可以收藏到本機瀏覽器、下載完整 Markdown 報告，或使用列印按鈕將五個分頁一起儲存為 PDF。</p>');
$('.close-dialog').onclick=()=>$('#info-dialog').close();
$('#info-dialog').addEventListener('click',e=>{if(e.target===$('#info-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#birthday').max=C.today();$('#year').textContent=new Date().getFullYear();render();
